INSERT INTO movies (id, title, original_title, year, country, language, genres, director, writer, cast_members, runtime_minutes, age_rating, advisories, moods, audio_languages, subtitle_languages, synopsis, import_note, first_import, released_on, poster, backdrop) VALUES
  ('last-screening', '마지막 상영', 'Ultima Proiecție', 2025, '루마니아', '루마니아어', ARRAY['드라마']::text[], '일리에 바르부', '소린 마테이', ARRAY['도이나 칼린', '미르체아 온치우', '라두 페트레']::text[], 112, 'all', ARRAY['주제']::text[], ARRAY['잔잔한', '여운이 남는']::text[], ARRAY['루마니아어']::text[], ARRAY['한국어', '영어']::text[], '문 닫는 동네 극장의 마지막 밤. 늙은 영사기사가 평생 돌린 필름을 마지막으로 걸며 객석에 모인 사람들의 시간을 되돌아본다.', '극장 개봉이 무산되어 영화제 상영에 그쳤던 작품을, 감독의 초기작까지 묶어 계약하고 들여왔습니다.', true, '2026-10-30', '/seed/last-screening-poster.svg', '/seed/last-screening-backdrop.svg'),
  ('winter-route', '겨울의 항로', 'Talvitie', 2024, '핀란드', '핀란드어', ARRAY['드라마', '모험']::text[], '아르보 린나마', '카이사 토르넬', ARRAY['에이노 살미', '린다 코스켈라', '파보 니에미']::text[], 128, '12', ARRAY['주제']::text[], ARRAY['긴장감 있는', '차가운']::text[], ARRAY['핀란드어']::text[], ARRAY['한국어', '영어']::text[], '얼어붙은 바다를 건너던 쇄빙선이 얼음에 갇힌다. 구조를 기다리는 선원들은 좁은 선실에서 서로를 견뎌야 한다.', '자국 개봉 뒤 해외 판매가 멈춰 있던 작품으로, 제작사와 직접 협상해 들여왔습니다.', true, '2026-10-23', '/seed/winter-route-poster.svg', '/seed/winter-route-backdrop.svg'),
  ('neon-rain', '네온 레인', 'Lluvia de Neón', 2026, '우루과이', '스페인어', ARRAY['스릴러', '범죄']::text[], '마르틴 소사', '파울라 레게이라', ARRAY['호아킨 베라', '루시아 알코바', '다니엘 프리에토']::text[], 104, '15', ARRAY['폭력성', '대사']::text[], ARRAY['스타일리시한', '어두운']::text[], ARRAY['스페인어']::text[], ARRAY['한국어', '영어']::text[], '비에 젖은 도심, 실종된 동생을 쫓던 택시 기사가 간판 불빛 아래에서 믿었던 사람들의 다른 얼굴을 본다.', '세계 판매사가 정해지기 전에 제작 단계에서 판권을 확보했습니다.', true, '2026-10-16', '/seed/neon-rain-poster.svg', '/seed/neon-rain-backdrop.svg'),
  ('silent-floor', '조용한 층', 'Ticho na Patře', 2025, '체코', '체코어', ARRAY['스릴러', '미스터리']::text[], '온드르제이 벨레크', '테레자 호우스코바', ARRAY['마르틴 하이느', '알레나 슬라마', '얀 크르제스탄']::text[], 97, '15', ARRAY['공포', '주제']::text[], ARRAY['서늘한', '밀실']::text[], ARRAY['체코어']::text[], ARRAY['한국어', '영어']::text[], '야근하는 직원들만 남은 빌딩에서 한 사람이 사라진다. 엘리베이터가 서지 않는 층의 불이 밤마다 켜진다.', '소규모 영화제 수상 뒤 국내 배급사 없이 남아 있던 작품입니다.', false, '2026-10-09', '/seed/silent-floor-poster.svg', '/seed/silent-floor-backdrop.svg'),
  ('glass-orbit', '유리 궤도', 'Klaasorbiit', 2026, '에스토니아', '에스토니아어', ARRAY['SF', '드라마']::text[], '카스파르 타미', '마리 렘베르그', ARRAY['리나 파울', '토마스 우이브', '하이디 옥사르']::text[], 118, '12', ARRAY['주제']::text[], ARRAY['고독한', '사색적인']::text[], ARRAY['에스토니아어']::text[], ARRAY['한국어', '영어']::text[], '궤도 정거장에 홀로 남은 관측원이 지구로 보내는 기록. 답신이 끊긴 뒤에도 그는 매일 같은 시각에 기록을 남긴다.', '해외 공개 전에 독점 계약을 맺어, 한국에서 처음으로 자막과 함께 공개합니다.', true, '2026-10-02', '/seed/glass-orbit-poster.svg', '/seed/glass-orbit-backdrop.svg'),
  ('second-sun', '두 번째 태양', 'İkinci Güneş', 2024, '튀르키예', '튀르키예어', ARRAY['SF', '모험']::text[], '오르한 일디즈', '세브다 카야', ARRAY['메르트 아크소이', '데파 일마즈', '부락 첼리크']::text[], 136, '12', ARRAY['폭력성']::text[], ARRAY['웅장한', '모험적인']::text[], ARRAY['튀르키예어']::text[], ARRAY['한국어', '영어']::text[], '하늘에 두 번째 태양이 뜬 뒤 물이 말라 가는 고원. 측량사와 유목민 소녀가 물이 남은 땅을 찾아 나선다.', '자국 흥행작이지만 해외 판매가 적었던 작품을 패키지 계약으로 들여왔습니다.', false, '2026-09-25', '/seed/second-sun-poster.svg', '/seed/second-sun-backdrop.svg'),
  ('spring-letter', '봄의 답장', 'Lettres de Printemps', 2025, '벨기에', '프랑스어', ARRAY['로맨스', '드라마']::text[], '엘로디 마르샹', '엘로디 마르샹', ARRAY['쥘리앵 라모트', '카미유 드프레', '노라 벤살']::text[], 109, 'all', ARRAY['주제']::text[], ARRAY['따뜻한', '잔잔한']::text[], ARRAY['프랑스어']::text[], ARRAY['한국어', '영어']::text[], '잘못 배달된 편지로 시작된 두 사람의 십 년. 서로의 얼굴을 모른 채 인생의 고비마다 답장이 오간다.', '감독의 전작을 함께 소개하는 조건으로 판권을 확보했습니다.', false, '2026-09-18', '/seed/spring-letter-poster.svg', '/seed/spring-letter-backdrop.svg'),
  ('midnight-bakery', '자정의 빵집', 'Pekara u Ponoć', 2023, '크로아티아', '크로아티아어', ARRAY['로맨스', '코미디']::text[], '이바 마티치', '고란 바비치', ARRAY['안테 코바치', '마야 슈테파니치', '루카 호르바트']::text[], 101, '12', ARRAY['대사']::text[], ARRAY['달콤한', '유쾌한']::text[], ARRAY['크로아티아어']::text[], ARRAY['한국어', '영어']::text[], '자정에만 문을 여는 빵집에 야간 근무자들이 모여든다. 무뚝뚝한 제빵사와 택시 기사의 느린 연애담.', '온라인 영화제에서 관객상을 받은 뒤 시네필 추천으로 수입을 결정했습니다.', false, '2026-09-11', '/seed/midnight-bakery-poster.svg', '/seed/midnight-bakery-backdrop.svg'),
  ('wrong-wedding', '엉뚱한 결혼식', 'O Casamento Errado', 2025, '포르투갈', '포르투갈어', ARRAY['코미디', '로맨스']::text[], '티아구 멘드스', '이네스 카발류', ARRAY['누누 파이바', '마르가리다 로샤', '주앙 피뉴']::text[], 95, '12', ARRAY['대사']::text[], ARRAY['유쾌한', '소동극']::text[], ARRAY['포르투갈어']::text[], ARRAY['한국어', '영어']::text[], '잘못 배달된 청첩장 한 장으로 낯선 결혼식에 간 남자가 신랑의 들러리가 되어 버린다.', '자국 코미디라 해외 소개가 드물었던 작품을 직접 찾아 계약했습니다.', false, '2026-09-04', '/seed/wrong-wedding-poster.svg', '/seed/wrong-wedding-backdrop.svg'),
  ('office-picnic', '사무실 소풍', 'Biuro na Pikniku', 2024, '폴란드', '폴란드어', ARRAY['코미디']::text[], '토마시 노박', '아그네시카 지엘린스카', ARRAY['파베우 보이치크', '카타지나 마주르', '미하우 렌']::text[], 89, '12', ARRAY['대사']::text[], ARRAY['풍자적인', '가벼운']::text[], ARRAY['폴란드어']::text[], ARRAY['한국어', '영어']::text[], '구조조정을 앞둔 회사가 단합을 위해 숲으로 소풍을 떠난다. 길을 잃은 직원들 사이에서 감춰 둔 명단이 돌기 시작한다.', '현지 텔레비전 방영 뒤 극장판으로 재편집된 판본을 들여왔습니다.', false, '2026-08-28', '/seed/office-picnic-poster.svg', '/seed/office-picnic-backdrop.svg'),
  ('iron-harbor', '철의 항구', 'Puerto de Hierro', 2026, '칠레', '스페인어', ARRAY['액션', '범죄']::text[], '곤살로 피네다', '카밀라 우르타도', ARRAY['세바스티안 로하스', '발렌티나 오르테가', '이그나시오 푸엔테스']::text[], 93, '15', ARRAY['폭력성', '모방위험']::text[], ARRAY['박진감 넘치는', '거친']::text[], ARRAY['스페인어']::text[], ARRAY['한국어', '영어']::text[], '컨테이너 부두 한 곳에서 벌어지는 90분의 탈출. 해고된 크레인 기사가 밀수 조직 한가운데에 갇힌다.', '촬영이 끝나기 전 러시 필름을 보고 선계약했습니다.', true, '2026-08-21', '/seed/iron-harbor-poster.svg', '/seed/iron-harbor-backdrop.svg'),
  ('night-express', '야간 급행', 'Nachtzug 44', 2023, '오스트리아', '독일어', ARRAY['액션', '스릴러']::text[], '루카스 힌터베르거', '안나 그루버', ARRAY['펠릭스 브란트너', '소피 라이터', '오토 메이어']::text[], 106, '15', ARRAY['폭력성']::text[], ARRAY['긴장감 있는', '빠른 전개']::text[], ARRAY['독일어']::text[], ARRAY['한국어', '영어']::text[], '국경을 넘는 야간열차에서 호송 중이던 증인이 사라진다. 다음 역까지 남은 시간은 한 시간.', '유럽 장르 영화 패키지에 포함된 작품입니다.', false, '2026-08-14', '/seed/night-express-poster.svg', '/seed/night-express-backdrop.svg'),
  ('salt-makers', '소금을 만드는 사람들', 'Marilis Mkhelebi', 2025, '조지아', '조지아어', ARRAY['다큐멘터리']::text[], '니노 베리제', '니노 베리제', ARRAY['기오르기 카파나제', '타마르 로미제']::text[], 84, 'all', ARRAY[]::text[], ARRAY['관조적인', '기록']::text[], ARRAY['조지아어']::text[], ARRAY['한국어', '영어']::text[], '사라져 가는 염전의 한 해를 내레이션 없이 기록한다. 바람과 햇볕에 맞춰 움직이는 노동의 리듬.', '다큐멘터리 영화제에서 발견해 감독과 직접 계약했습니다.', true, '2026-08-07', '/seed/salt-makers-poster.svg', '/seed/salt-makers-backdrop.svg'),
  ('city-of-pigeons', '비둘기의 도시', 'Aghavnineri Kaghak', 2024, '아르메니아', '아르메니아어', ARRAY['다큐멘터리']::text[], '아르멘 사르키산', '릴리트 하코비안', ARRAY['바르단 가스파리안', '아니 마누키안']::text[], 78, 'all', ARRAY[]::text[], ARRAY['소박한', '기록']::text[], ARRAY['아르메니아어']::text[], ARRAY['한국어', '영어']::text[], '옥상에서 비둘기를 키우는 사람들과 함께 도시의 변화를 지켜본다. 재개발이 다가오자 새들의 집도 줄어든다.', '국내 상영 기록이 없던 작품을 다큐멘터리 묶음으로 들여왔습니다.', false, '2026-07-31', '/seed/city-of-pigeons-poster.svg', '/seed/city-of-pigeons-backdrop.svg'),
  ('paper-whale', '종이 고래', 'Pappersvalen', 2026, '스웨덴', '스웨덴어', ARRAY['애니메이션', '가족', '판타지']::text[], '엘린 벡스트룀', '요나스 린드', ARRAY['스벤 달', '마야 에크', '알바 호름']::text[], 88, 'all', ARRAY[]::text[], ARRAY['따뜻한', '환상적인']::text[], ARRAY['스웨덴어', '한국어']::text[], ARRAY['한국어', '영어']::text[], '바다를 본 적 없는 아이가 접은 종이 고래가 어느 밤 하늘로 헤엄쳐 오른다. 고래를 따라 떠난 아이의 여행.', '한국어 더빙까지 함께 제작해 공개합니다.', true, '2026-07-24', '/seed/paper-whale-poster.svg', '/seed/paper-whale-backdrop.svg'),
  ('little-lighthouse', '작은 등대', 'Mazā Bāka', 2023, '라트비아', '라트비아어', ARRAY['애니메이션', '가족', '모험']::text[], '안드리스 칼닌시', '일제 오졸라', ARRAY['야니스 베르진시', '크리스티네 리에파', '마르틴시 오졸스']::text[], 76, 'all', ARRAY[]::text[], ARRAY['아기자기한', '모험적인']::text[], ARRAY['라트비아어', '한국어']::text[], ARRAY['한국어', '영어']::text[], '바닷가 마을의 등대를 지키는 아이가 폭풍우 치는 밤 길 잃은 배를 부른다.', '어린이 영화제 수상작으로, 한국어 더빙판을 함께 공개합니다.', false, '2026-07-17', '/seed/little-lighthouse-poster.svg', '/seed/little-lighthouse-backdrop.svg'),
  ('dust-sheriff', '먼지의 보안관', 'El Sheriff del Polvo', 2025, '아르헨티나', '스페인어', ARRAY['서부', '액션']::text[], '에르난 바르가스', '솔 메디나', ARRAY['라몬 아기레', '플로렌시아 파스', '토마스 게라']::text[], 119, '15', ARRAY['폭력성']::text[], ARRAY['쓸쓸한', '묵직한']::text[], ARRAY['스페인어']::text[], ARRAY['한국어', '영어']::text[], '철도가 비껴간 뒤 몰락한 마을, 은퇴를 앞둔 보안관에게 마지막 사건이 찾아온다.', '남미 서부극을 찾던 시네필 큐레이터의 추천으로 판권을 확보했습니다.', true, '2026-07-10', '/seed/dust-sheriff-poster.svg', '/seed/dust-sheriff-backdrop.svg'),
  ('last-cartographer', '마지막 지도 제작자', 'Den Sidste Kartograf', 2024, '덴마크', '덴마크어', ARRAY['모험', '드라마']::text[], '마그누스 호이', '프레야 달가르드', ARRAY['라스 빈테르', '이다 쇠렌센', '에밀 크로그']::text[], 124, 'all', ARRAY['주제']::text[], ARRAY['사색적인', '광활한']::text[], ARRAY['덴마크어']::text[], ARRAY['한국어', '영어']::text[], '위성 지도가 세상을 뒤덮은 시대, 손으로 지도를 그리는 노인이 마지막 미측량 지역으로 떠난다.', '현지 개봉 후 해외 판매가 없던 작품을 직접 계약했습니다.', false, '2026-07-03', '/seed/last-cartographer-poster.svg', '/seed/last-cartographer-backdrop.svg'),
  ('island-of-clocks', '시계의 섬', 'Eyja Klukkanna', 2026, '아이슬란드', '아이슬란드어', ARRAY['모험', '판타지', '가족']::text[], '시그뤼나 욘스도티르', '에이나르 베르그', ARRAY['크리스틴 올라프스', '비외른 하랄즈', '소피아 군나르스']::text[], 98, 'all', ARRAY[]::text[], ARRAY['환상적인', '따뜻한']::text[], ARRAY['아이슬란드어', '한국어']::text[], ARRAY['한국어', '영어']::text[], '고장 난 회중시계를 고치러 떠난 남매가 구역마다 시간이 다르게 흐르는 섬에 닿는다.', '수입이 확정되어 한국어 자막과 더빙을 작업하고 있습니다.', true, '2027-01-15', '/seed/island-of-clocks-poster.svg', '/seed/island-of-clocks-backdrop.svg'),
  ('fourth-witness', '네 번째 증인', 'Štvrtý Svedok', 2025, '슬로바키아', '슬로바키아어', ARRAY['범죄', '미스터리']::text[], '페테르 코바치크', '주자나 바르타', ARRAY['미하엘 도브로', '에바 호라', '이고르 네메츠']::text[], 115, '15', ARRAY['폭력성', '주제']::text[], ARRAY['치밀한', '반전']::text[], ARRAY['슬로바키아어']::text[], ARRAY['한국어', '영어']::text[], '세 증인의 진술로 재구성된 살인 사건에, 존재하지 않았던 네 번째 증인이 나타난다.', '영화제 경쟁 부문 상영 직후 계약했습니다.', false, '2026-06-26', '/seed/fourth-witness-poster.svg', '/seed/fourth-witness-backdrop.svg'),
  ('pawnshop-ledger', '전당포 장부', 'Libro de Empeños', 2023, '페루', '스페인어', ARRAY['범죄', '드라마']::text[], '카를로스 킨테로', '로사 우아망', ARRAY['후안 파리', '엘레나 마마니', '디에고 카세레스']::text[], 108, '15', ARRAY['주제', '대사']::text[], ARRAY['씁쓸한', '느린 긴장']::text[], ARRAY['스페인어']::text[], ARRAY['한국어', '영어']::text[], '폐업을 앞둔 전당포의 장부에 지역 유지들의 비밀이 적혀 있다. 물건을 찾으러 온 사람들의 발길이 이어진다.', '안데스 지역 영화 특별전을 준비하며 찾아낸 작품입니다.', false, '2026-06-19', '/seed/pawnshop-ledger-poster.svg', '/seed/pawnshop-ledger-backdrop.svg'),
  ('grandma-submarine', '할머니의 잠수함', 'Bestemors Ubåt', 2026, '노르웨이', '노르웨이어', ARRAY['가족', '코미디']::text[], '잉리드 할보르센', '올라 스트란드', ARRAY['군힐드 뵈', '토르 리', '아스트리드 모엔']::text[], 92, 'all', ARRAY[]::text[], ARRAY['유쾌한', '따뜻한']::text[], ARRAY['노르웨이어', '한국어']::text[], ARRAY['한국어', '영어']::text[], '칠순의 할머니가 뒷마당에서 잠수함을 만들어 손자와 함께 바다로 나선다.', '가족 영화 라인업을 위해 공개 전에 선계약했습니다.', true, '2027-02-05', '/seed/grandma-submarine-poster.svg', '/seed/grandma-submarine-backdrop.svg'),
  ('moving-day', '이삿날의 식탁', 'Cena de Mudanza', 2024, '볼리비아', '스페인어', ARRAY['가족', '드라마']::text[], '파트리시아 초케', '안드레스 수아레스', ARRAY['마르타 키스페', '루이스 콘도리', '이네스 바르가스']::text[], 94, 'all', ARRAY['주제']::text[], ARRAY['잔잔한', '여운이 남는']::text[], ARRAY['스페인어', '한국어']::text[], ARRAY['한국어', '영어']::text[], '삼십 년 산 집을 떠나는 날, 다 큰 삼 남매가 짐을 싸러 모이고 상자마다 오래된 다툼이 나온다.', '국내 상영 기록이 없던 작품을 처음 소개합니다.', false, '2026-06-12', '/seed/moving-day-poster.svg', '/seed/moving-day-backdrop.svg'),
  ('fog-kingdom', '안개 왕국의 서기', 'Rūko Karalystės Raštininkas', 2025, '리투아니아', '리투아니아어', ARRAY['판타지', '모험']::text[], '요나스 페트라우스카스', '루타 카즐라', ARRAY['도비다스 발트루스', '에글레 바란', '마리우스 얀쿠스']::text[], 131, '12', ARRAY['폭력성']::text[], ARRAY['신비로운', '지적인']::text[], ARRAY['리투아니아어']::text[], ARRAY['한국어', '영어']::text[], '왕의 말을 기록하는 말단 서기가 왕국의 역사가 조작되었음을 알게 된다. 칼 대신 문서로 싸우는 판타지.', '판타지 영화제 상영본을 보고 시네필 관객의 요청을 받아 수입했습니다.', true, '2026-06-05', '/seed/fog-kingdom-poster.svg', '/seed/fog-kingdom-backdrop.svg'),
  ('moon-weaver', '달을 짜는 사람', 'Saran Nekhmelch', 2023, '몽골', '몽골어', ARRAY['판타지', '로맨스']::text[], '바트바야르 도르지', '오윤 체렌', ARRAY['툴가 간바트', '사랑 나란', '에르덴 바야르']::text[], 103, 'all', ARRAY[]::text[], ARRAY['설화적인', '서정적인']::text[], ARRAY['몽골어']::text[], ARRAY['한국어', '영어']::text[], '밤마다 달빛으로 천을 짜는 직녀와 그 천을 팔러 다니는 행상의 이야기. 달이 기울수록 천은 짧아진다.', '중앙아시아 영화 묶음 계약으로 들여왔습니다.', false, '2026-05-29', '/seed/moon-weaver-poster.svg', '/seed/moon-weaver-backdrop.svg'),
  ('court-archivist', '사관의 붓', 'Sử Quan', 2026, '베트남', '베트남어', ARRAY['역사', '드라마']::text[], '응우옌 반 호아', '쩐 티 란', ARRAY['레 민 득', '팜 투 하', '호앙 꽝']::text[], 139, '12', ARRAY['주제', '폭력성']::text[], ARRAY['묵직한', '정치극']::text[], ARRAY['베트남어']::text[], ARRAY['한국어', '영어']::text[], '왕의 곁에서 모든 것을 기록해야 하는 젊은 사관이 왕의 치부를 목격한다. 붓을 들 것인가, 내려놓을 것인가.', '수입이 확정되어 역사 용어 감수와 자막 작업을 진행하고 있습니다.', true, '2027-03-12', '/seed/court-archivist-poster.svg', '/seed/court-archivist-backdrop.svg'),
  ('ninth-bridge', '아홉 번째 다리', 'Deveti Most', 2024, '세르비아', '세르비아어', ARRAY['전쟁', '역사']::text[], '밀로시 요바노비치', '드라가나 일리치', ARRAY['네마냐 페트로비치', '요반 마르코비치', '사냐 니콜리치']::text[], 142, '15', ARRAY['폭력성', '주제']::text[], ARRAY['묵직한', '긴장감 있는']::text[], ARRAY['세르비아어']::text[], ARRAY['한국어', '영어']::text[], '후퇴하는 공병대가 강 위의 다리 아홉 개를 차례로 폭파하라는 명령을 받는다. 마지막 다리 앞에는 피란민이 있다.', '복원판 공개에 맞춰 판권을 확보했습니다.', false, '2026-05-22', '/seed/ninth-bridge-poster.svg', '/seed/ninth-bridge-backdrop.svg'),
  ('radio-silence', '무전 침묵', 'Radijska Tišina', 2025, '슬로베니아', '슬로베니아어', ARRAY['전쟁', '스릴러']::text[], '마티야 코프리브니크', '우르샤 젤레즈니크', ARRAY['얀 포드고르니크', '티나 크라니', '블라시 구베츠']::text[], 99, '15', ARRAY['폭력성', '공포']::text[], ARRAY['숨 막히는', '밀실']::text[], ARRAY['슬로베니아어']::text[], ARRAY['한국어', '영어']::text[], '적진 한가운데 고립된 통신병 세 사람. 무전을 켜면 들키고 끄면 구조가 끊긴다.', '소규모 영화제에서 발견해 배급사 없이 직접 계약했습니다.', true, '2026-05-15', '/seed/radio-silence-poster.svg', '/seed/radio-silence-backdrop.svg'),
  ('basement-tenant', '지하의 세입자', 'Mazeto Naemateli', 2026, '불가리아', '불가리아어', ARRAY['공포', '미스터리']::text[], '스토얀 디미트로프', '밀레나 토도로바', ARRAY['이반 게오르기예프', '데시슬라바 콜레바', '플라멘 스타네프']::text[], 96, '15', ARRAY['공포', '주제']::text[], ARRAY['오싹한', '서늘한']::text[], ARRAY['불가리아어']::text[], ARRAY['한국어', '영어']::text[], '오래된 다세대 주택을 물려받은 주인공이 임대 장부에서 존재하지 않는 지하층의 세입자를 발견한다.', '심야 상영에서 화제가 된 뒤 해외 판매가 시작되기 전에 계약했습니다.', true, '2026-05-08', '/seed/basement-tenant-poster.svg', '/seed/basement-tenant-backdrop.svg'),
  ('hollow-school', '빈 학교의 종소리', 'Këmbanat', 2023, '알바니아', '알바니아어', ARRAY['공포', '스릴러']::text[], '아르벤 호자', '엘로나 샤피', ARRAY['드리탄 메타', '브리켈다 추피', '겐티안 칼라']::text[], 91, '15', ARRAY['공포']::text[], ARRAY['오싹한', '어두운']::text[], ARRAY['알바니아어']::text[], ARRAY['한국어', '영어']::text[], '폐교로 담력 시험을 떠난 대학생들. 울릴 리 없는 종소리가 울리자 교실 문이 하나씩 닫힌다.', '장르 영화 패키지에 포함된 작품입니다.', false, '2026-05-01', '/seed/hollow-school-poster.svg', '/seed/hollow-school-backdrop.svg'),
  ('last-cassette', '마지막 카세트', 'Akher Cassette', 2024, '튀니지', '아랍어', ARRAY['음악', '드라마']::text[], '카림 벤 아마르', '살마 트라벨시', ARRAY['야신 가르비', '아미라 부알레그', '무니르 자이디']::text[], 110, 'all', ARRAY['주제']::text[], ARRAY['서정적인', '여운이 남는']::text[], ARRAY['아랍어']::text[], ARRAY['한국어', '영어']::text[], '아버지의 유품에서 나온 카세트테이프 한 개가 딸을 낯선 소도시로 이끈다. 테이프 속 목소리의 주인을 찾는 여정.', '북아프리카 영화 특별전을 준비하며 들여왔습니다.', false, '2026-04-24', '/seed/last-cassette-poster.svg', '/seed/last-cassette-backdrop.svg'),
  ('brass-street', '금관의 거리', 'Calle de los Metales', 2025, '쿠바', '스페인어', ARRAY['음악', '코미디']::text[], '오스카르 리베라', '욜란다 페르난데스', ARRAY['레오넬 산토스', '마리엘라 크루스', '에르네스토 디아스']::text[], 102, 'all', ARRAY[]::text[], ARRAY['흥겨운', '유쾌한']::text[], ARRAY['스페인어']::text[], ARRAY['한국어', '영어']::text[], '철거를 앞둔 상가의 상인들이 보상금 협상 대신 금관 악단을 결성한다. 악기를 처음 잡아 본 사람들의 행진.', '음악 영화제에서 관객상을 받은 뒤 계약했습니다.', false, '2026-04-17', '/seed/brass-street-poster.svg', '/seed/brass-street-backdrop.svg'),
  ('lake-disappearance', '호수가 사라진 날', 'Ezers Pazuda', 2026, '라트비아', '라트비아어', ARRAY['미스터리', 'SF']::text[], '마티스 칼바', '리가 오졸린야', ARRAY['에드가르스 빈클레르', '다체 루드', '카를리스 스프로기스']::text[], 113, '12', ARRAY['주제']::text[], ARRAY['기묘한', '사색적인']::text[], ARRAY['라트비아어']::text[], ARRAY['한국어', '영어']::text[], '어느 날 아침 작은 마을의 호수가 물 한 방울 남기지 않고 사라진다. 드러난 바닥에서 마을이 숨겨 온 것들이 나온다.', '공개 직후 시네필 커뮤니티의 추천을 받아 가장 먼저 계약했습니다.', true, '2026-04-10', '/seed/lake-disappearance-poster.svg', '/seed/lake-disappearance-backdrop.svg'),
  ('sunday-special', '일요일 특집극', 'Nedelna Emisija', 2023, '북마케도니아', '마케도니아어', ARRAY['코미디', '드라마']::text[], '블라디미르 스토야노브', '이바나 트라이코브스카', ARRAY['고체 니콜로브', '실바나 조르제브스카', '니콜라 리스토브']::text[], 87, 'all', ARRAY[]::text[], ARRAY['유쾌한', '따뜻한']::text[], ARRAY['마케도니아어']::text[], ARRAY['한국어', '영어']::text[], '폐국을 앞둔 방송국 사람들이 마지막 일요일 특집극을 만든다. 예산도 시간도 없는 현장의 하루.', '국내 소개된 적 없는 발칸 코미디를 찾아 들여왔습니다.', false, '2026-04-03', '/seed/sunday-special-poster.svg', '/seed/sunday-special-backdrop.svg'),
  ('night-desk', '심야 보도국', 'Nocna Redakcja', 2024, '폴란드', '폴란드어', ARRAY['드라마', '범죄']::text[], '마우고자타 시코라', '야쿠프 두다', ARRAY['크시슈토프 바란', '모니카 파블락', '아담 코즈워프스키']::text[], 105, '12', ARRAY['주제', '대사']::text[], ARRAY['치밀한', '건조한']::text[], ARRAY['폴란드어']::text[], ARRAY['한국어', '영어']::text[], '지역 방송국의 심야 뉴스 팀이 경찰 내부 비리 제보를 받는다. 방송까지 남은 시간은 여섯 시간.', '언론 소재 영화를 찾던 시네필 큐레이터의 제안으로 들여왔습니다.', false, '2026-03-27', '/seed/night-desk-poster.svg', '/seed/night-desk-backdrop.svg'),
  ('wolves-border', '국경의 늑대들', 'Lobos de la Frontera', 2026, '파라과이', '스페인어', ARRAY['서부', '스릴러']::text[], '네스토르 베니테스', '아드리아나 곤살레스', ARRAY['파블로 아얄라', '미리암 카바예로', '우고 비야그라']::text[], 117, '15', ARRAY['폭력성']::text[], ARRAY['거친', '긴장감 있는']::text[], ARRAY['스페인어']::text[], ARRAY['한국어', '영어']::text[], '가축 도둑을 쫓던 목장 일꾼들이 국경 너머에서 더 큰 범죄를 발견한다.', '수입이 확정되어 공개를 준비하고 있습니다.', true, '2027-04-02', '/seed/wolves-border-poster.svg', '/seed/wolves-border-backdrop.svg');
